        s = s.replace(DISPATCH_ANCHOR, DISPATCH_SNIPPET + DISPATCH_ANCHOR, 1)
        srv.write_text(s, encoding="utf-8")
        out["dispatch"] = f"patched(+{len(TOOL_SCHEMA)})"
    else:
        out["dispatch"] = "anchor-missing"

