# -*- coding: utf-8 -*-
"""sop_audit —— SOP 自身的独立审计（元校验）。回答「如何避免 SOP 错误」。

核心立场：
  **规范来自外部权威，不来自观察。** 本工具只做**双向对账**，不生成 SOP —— 否则
  就变成「以事实定义标准」，SOP 会退化成「当前实现的描述」，失去标准作用。

四道校验：
  ① 结构性：id 唯一 / 依赖可解析 / 顺序无环 / 脚本存在
  ② **双向对账**（关键）：
       实现会写而 SOP 未声明 → `spec_gap`（SOP 漏项，**规范缺口**）
       SOP 声明而实现不写   → `phantom_binding`（SOP 幻觉，**绑定错误**）
     证据来源与 SOP 相互独立：对 build/*.py 做 AST 扫描，提取 write_text/json.dump 等
     写出目标的**路径常量**。
  ③ 权威性：每条产物声明必须标注 `source`（规范来自哪个权威），缺失即 `ungrounded`
  ④ 变更受限：读 sop_changelog.yaml —— 若本版 SOP 删/降级了 must_produce 而无批准标记，
     即 `unapproved_spec_change`（堵「改 SOP 让它通过」）
"""
from __future__ import annotations

import ast
import json
import re
from pathlib import Path

WS = Path(__file__).resolve().parent.parent.parent
HERE = WS / "build" / "sop"
BUILD = WS / "build"


def _sop() -> dict:
    import yaml
    return yaml.safe_load((HERE / "sop.yaml").read_text(encoding="utf-8")) or {}


def scan_write_targets() -> dict[str, set[str]]:
    """对每个脚本做 AST 扫描，提取它**写出**的路径常量（与 SOP 独立的一手证据）。"""
    out: dict[str, set[str]] = {}
    for py in sorted(BUILD.glob("*.py")):
        if py.name.startswith("sop"):
            continue
        try:
            tree = ast.parse(py.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        targets: set[str] = set()
        for n in ast.walk(tree):
            if isinstance(n, ast.Call):
                fn = ""
                if isinstance(n.func, ast.Attribute):
                    fn = n.func.attr
                elif isinstance(n.func, ast.Name):
                    fn = n.func.id
                if fn in ("write_text", "write_bytes", "dump", "dump_all", "writestr", "write"):
                    # 收集本次调用里出现的字符串常量（可能是文件名或目录名）
                    for a in ast.walk(n):
                        if isinstance(a, ast.Constant) and isinstance(a.value, str):
                            v = a.value
                            if re.search(r"\.(yaml|json|jsonl|md|docx|zip|txt)$", v) or "/" in v:
                                targets.add(v)
        if targets:
            out[py.name] = targets
    return out


def audit() -> dict:
    doc = _sop()
    stages = doc.get("stages") or []
    writes = scan_write_targets()
    issues: list[dict] = []

    # ① 结构性
    ids = [s["id"] for s in stages]
    if len(ids) != len(set(ids)):
        issues.append({"kind": "dup_id", "detail": "环节 id 重复"})
    for s in stages:
        if not (BUILD / s["script"]).exists():
            issues.append({"kind": "missing_script", "stage": s["id"],
                           "detail": f"脚本不存在：{s['script']}"})

