# -*- coding: utf-8 -*-
"""apply_decisions —— 把**人工决策**应用到 SOP（SOP 只在此处被改，且必须留痕）。

硬约束（防橡皮图章）：
  ① 决策文件必须含 `choice` / `rationale` / `decided_by` / `decided_at`，缺一即拒绝；
  ② `change_type: spec`（改规范：增删 must_produce/产物声明）需 `approved_by`，否则拒绝；
  ③ 应用后必须写 sop_changelog.yaml 并**重新冻结** sop.sha256；
  ④ 不做任何「猜测性修补」——只执行决策里显式写的动作。
"""
from __future__ import annotations

import hashlib
import json
import sys
from pathlib import Path

WS = Path(__file__).resolve().parent.parent.parent
HERE = WS / "build" / "sop"
DEC = HERE / "decisions"
REQ = ("choice", "rationale", "decided_by", "decided_at")


def _y(p: Path, d=None):
    import yaml
    try:
        return yaml.safe_load(p.read_text(encoding="utf-8")) or d
    except Exception:                                     # noqa: BLE001
        return d


def _w(p: Path, o):
    import yaml
    p.write_text(yaml.safe_dump(o, allow_unicode=True, sort_keys=False, width=110), encoding="utf-8")


def apply_one(d: dict) -> dict:
    miss = [k for k in REQ if not d.get(k)]
    if miss:
        return {"applied": False, "why": f"决策缺字段 {miss} —— 拒绝应用（不得无记名决策）"}
    ct = d.get("change_type", "binding")
    if ct == "spec" and not d.get("approved_by"):
        return {"applied": False, "why": "规范变更缺少 approved_by —— 拒绝应用"}
    sop = _y(HERE / "sop.yaml", {}) or {}
    stages = {s["id"]: s for s in sop.get("stages") or []}
    st = stages.get(d.get("stage"))
    if not st:
        return {"applied": False, "why": f"SOP 中无环节 {d.get('stage')}"}
    act = d.get("action") or {}
    kind = act.get("kind")
    before = json.dumps(st, ensure_ascii=False)
    if kind == "set_output_source":
        st["output_source"] = act["value"]
    elif kind == "add_output":
        st.setdefault("outputs", [])
        if act["value"] not in st["outputs"]:
            st["outputs"].append(act["value"])
        if act.get("output_source"):
            st["output_source"] = act["output_source"]
        st.pop("outputs_pending_review", None)
    elif kind == "replace_binding":
        st["outputs"] = [act["new"] if o == act["old"] else o for o in st.get("outputs") or []]
    elif kind == "mark_non_deliverable":
        st["outputs"] = []
        st["non_deliverable_reason"] = act.get("reason", "")
        st.pop("outputs_pending_review", None)
    elif kind == "downgrade_to_binding":
        st["output_source"] = "implementation-binding（非规范）"
    else:
        return {"applied": False, "why": f"未知动作 {kind}"}

    _w(HERE / "sop.yaml", sop)
