# -*- coding: utf-8 -*-
"""calibrate_scanner —— 标定 AST 扫描器（先标定，后采信）。

未标定的探针不得采信（本项目已有 3 次探针假阳性的教训）。
标定 = 用**已知正样本**（anchor）测扫描器的**召回与精确**，不达标则收紧后重测。

锚点（anchor）：「我确定 S 环节产出 X」的事实，来自本会话的实测产物，不来自扫描器。
标定通过后写 scanner_calibrated 标记与证据文件，L2 项才升为 L1 参与决策。
"""
from __future__ import annotations

import ast
import json
import re
from pathlib import Path

WS = Path(__file__).resolve().parent.parent.parent
BUILD = WS / "build"
HERE = WS / "build" / "sop"

WRITE_ATTRS = {"write_text", "write_bytes", "dump", "dump_all", "writestr", "write", "savefig"}
WRITE_FUNCS = {"open", "writestr"}


def _consts(node) -> list[str]:
    return [a.value for a in ast.walk(node) if isinstance(a, ast.Constant) and isinstance(a.value, str)]


def scan_script(py: Path) -> set[str]:
    """收紧后的扫描：只取**直接写在写调用上的路径表达式**里的字符串常量。

    旧版对整棵 Call 子树做 ast.walk，把嵌套调用里的无关常量也收进来 —— 这是噪声来源。
    """
    try:
        tree = ast.parse(py.read_text(encoding="utf-8"))
    except SyntaxError:
        return set()
    out: set[str] = set()
    for n in ast.walk(tree):
        if not isinstance(n, ast.Call):
            continue
        fn = n.func.attr if isinstance(n.func, ast.Attribute) else (
            n.func.id if isinstance(n.func, ast.Name) else "")
        if fn in WRITE_ATTRS and isinstance(n.func, ast.Attribute):
            # 写法： (expr).write_text(...) —— expr 即被写对象，取其路径常量
            for c in _consts(n.func.value):
                if re.search(r"\.(yaml|yml|json|jsonl|md|docx|zip|txt|csv)$", c) or "/" in c:
                    out.add(c)
        elif fn == "writestr" and len(n.args) >= 1:          # zip 条目名
            for c in _consts(n.args[0]):
                out.add(c)
        elif fn == "open" and n.args:
            mode = [c for c in _consts(n.args[1])] if len(n.args) > 1 else []
            if any("w" in m for m in mode):
                for c in _consts(n.args[0]):
                    if "/" in c or re.search(r"\.\w+$", c):
                        out.add(c)
    return out


# 已知正样本（anchor）：来自本会话实测，**不是**扫描器的输出
ANCHORS = [
    ("s0_docx2md.py",           ["大数据研究中心可研.md"]),
    ("s4_pipeline.py",          ["manifest.yaml"]),
    ("s7b_desensitize.py",      ["skeletons.jsonl"]),
    ("s10_external.py",         ["documents.yaml", "chunks.jsonl", "mandates.yaml"]),
    ("opt25.py",                ["source_ledger.json", "relations.yaml"]),
    ("s32_external_docs_merge.py", ["documents.yaml", "external_merge_report.yaml"]),
    ("gt29_toolkit.py",         ["sentences.jsonl"]),
    ("s6_domains.py",           ["domains.yaml"]),
    ("s31_gates_upstream.py",   ["verify_pipeline.yaml", "closure_report.yaml"]),
    ("s9_screened_bundle.py",   [".zip"]),
]


def calibrate() -> dict:
    rows, tp, fn_, fp_unrelated = [], 0, 0, 0
    for script, expects in ANCHORS:
        p = BUILD / script
        got = scan_script(p) if p.exists() else set()
        hits = {e: any(e in g for g in got) for e in expects}
        ok = all(hits.values())
        tp += sum(1 for v in hits.values() if v)
        fn_ += sum(1 for v in hits.values() if not v)
        rows.append({"script": script, "expect": expects, "found": sorted(got)[:8],
                     "hit": hits, "pass": ok})
    recall = tp / max(tp + fn_, 1)
    # 精确性：任一 anchor 产物是否被**无关脚本**也声称写出
    all_map = {s: scan_script(BUILD / s) for s, _ in ANCHORS}
    for s, exps in ANCHORS:
        for other, tgts in all_map.items():
            if other == s:
                continue
            for e in exps:
                if any(e in t for t in tgts):
                    fp_unrelated += 1
