import json, re
from pathlib import Path
R = Path("SHUFE-BDC-2019-001")
idx = json.loads((R/"index/node_index.json").read_text(encoding="utf-8"))
print("node_index.json 类型:", type(idx).__name__, "| 元素数:", len(idx))
print("样例元素:", json.dumps(idx[0], ensure_ascii=False)[:200] if idx else "空")
# 收集各空间的 id
def ids_of(p, key="id"):
    try:
        d = json.loads(Path(p).read_text(encoding="utf-8"))
    except Exception:
        return set()
    out = set()
    def walk(o):
        if isinstance(o, dict):
            for k, v in o.items():
                if k == key and isinstance(v, str): out.add(v)
                walk(v)
        elif isinstance(o, list):
            for x in o: walk(x)
    walk(d); return out
space = {}
for f in ("graph/nodes.yaml", "graph/nodes.base.yaml", "graph/graph.yaml",
          "evidence/evidence.yaml", "chunks/chunks.jsonl"):
    p = R/f
    if not p.exists(): continue
    if p.suffix == ".jsonl":
        s = set()
        for line in p.read_text(encoding="utf-8").splitlines():
            if line.strip(): s |= set(re.findall(r'"(N-[0-9a-f]{12})"', line))
        space[f] = s
    else:
        space[f] = ids_of(p)
allspace = set().union(*space.values()) if space else set()
idx_ids = {x for x in idx if isinstance(x, str)} if all(isinstance(x, str) for x in idx[:5]) else set()
if not idx_ids:
    s = json.dumps(idx, ensure_ascii=False)
    idx_ids = set(re.findall(r'"(N-[0-9a-f]{12})"', s))
print("\nnode_index 中的 N- id:", len(idx_ids))
for k, v in space.items():
    print(f"  {k:30s} 含 {len(v):5d} 个 N- id | 与 index 交集 {len(idx_ids & v):5d}")
print(f"  全部空间并集: {len(allspace)} | 与 index 交集 {len(idx_ids & allspace)}")
lost = idx_ids - allspace
print(f"\n  **index 独有（任何地方都找不到）: {len(lost)}**")
print("  样例:", sorted(lost)[:5])
PYEOF", "description": "Triage the unresolvable index IDs"}

