         "declared_outputs": record.get("declared_outputs") or [],
         "produced": [{"path": o["path"], "sha256": o["sha256"], "bytes": o["bytes"]}
                      for o in (record.get("outputs") or [])],
         "source": "A=上游自报（可能虚报，故须与 B/C/SOP 交叉）"}
